function nodenoLegalCorpus(string $directory,string $locale):array {
 if(!in_array($locale,NODENO_STORE_LOCALES,true))throw new InvalidArgumentException('legal_locale_invalid');
 $data=json_decode((string)file_get_contents($directory.'/site-documents.'.$locale.'.json'),true,64,JSON_THROW_ON_ERROR);
 if(($data['locale']??null)!==$locale||!is_array($data['documents']??null))throw new RuntimeException('legal_documents_unavailable');return $data;
}
function nodenoLegalPage(array $corpus,string $id,array $seller):string {
 $locale=$corpus['locale'];$labels=nodenoLegalLabels($locale);$e='nodenoLegalEscape';$docs=$corpus['documents'];
 foreach(['pre-information','sales','returns','seller']as $kind){
  $text=$kind==='seller'?implode("\n",array_filter([$seller['name']??'', $seller['address']??'', $seller['email']??'', 'info@nodenohome.com', '0850 305 84 78'])):(nodenoLocaleDocument($seller[$kind==='returns'?'returns':'terms']??[],$locale));
  if($text!=='')$docs[]=['id'=>$kind,'title'=>$labels[$kind],'summary'=>'','version'=>$seller['termsVersion']??'','sections'=>[['title'=>'','paragraphs'=>preg_split('/\n\n/',$text)]]];
 }
 $active=null;foreach($docs as $doc)if($doc['id']===$id)$active=$doc;
 if($id!==''&&$active===null)throw new InvalidArgumentException('legal_document_not_found');
 $title=$active['title']??$labels['centre'];$nav='';foreach($docs as $doc)$nav.='<a href="/legal/'.$e($doc['id']).'?lang='.$locale.'"'.($doc['id']===$id?' aria-current="page"':'').'>'.$e($doc['title']).'</a>';
 $content='';if($active){$content='<h1>'.$e($title).'</h1><p class="legal-version">'.$e($labels['version']).': '.$e($active['version']??$corpus['version']).'</p><p class="legal-lead">'.$e($active['summary']??'').'</p>';foreach($active['sections']as $section){$content.='<section>'.($section['title']!==''?'<h2>'.$e($section['title']).'</h2>':'');foreach($section['paragraphs']as $paragraph)$content.='<p>'.nl2br($e($paragraph)).'</p>';$content.='</section>';}}
 else{$content='<h1>'.$e($title).'</h1><p class="legal-lead">'.$e($labels['intro']).'</p><div class="legal-cards">';foreach($docs as $doc)$content.='<a href="/legal/'.$e($doc['id']).'?lang='.$locale.'"><h2>'.$e($doc['title']).'</h2><p>'.$e($doc['summary']??'').'</p></a>';$content.='</div>';}
 $languages='';foreach(['tr'=>'Türkçe','en'=>'English','ru'=>'Русский','ar'=>'العربية','de'=>'Deutsch','az'=>'Azərbaycanca','kk'=>'Қазақша','tk'=>'Türkmençe','uz'=>'Oʻzbekcha','ky'=>'Кыргызча','fa'=>'فارسی']as $key=>$label)$languages.='<a href="/legal'.($id!==''?'/'.$e($id):'').'?lang='.$key.'" lang="'.$key.'"'.($key===$locale?' aria-current="page"':'').'>'.$label.'</a>';
 $actions=$active?'<div class="legal-actions"><button type="button" data-legal-print>'.$e($labels['print']).'</button><a href="?lang='.$locale.'&amp;download=1" download>'.$e($labels['download']).'</a>'.($id==='cookies'?'<button type="button" data-legal-preferences>'.$e($labels['preferences']).'</button>':'').'</div>':'';
 return '<!doctype html><html lang="'.$locale.'" dir="'.(nodenoLocaleRtl($locale)?'rtl':'ltr').'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.$e($title).' | NODENO</title><meta name="description" content="'.$e($active['summary']??$labels['intro']).'"><link rel="stylesheet" href="/legal.css?v=storefront-recovery-20261112-r1"><script type="module" src="/legal.js?v=storefront-recovery-20261112-r1"></script></head><body class="legal-page"><header><a href="/?lang='.$locale.'"><img src="/assets/brand/logo-horizontal.svg?v=social-keywords-20261113-v6" width="222" height="50" alt="NODENO"></a><a href="/?lang='.$locale.'">'.$e($labels['home']).'</a></header><div class="legal-language">'.$languages.'</div><div class="legal-layout"><nav aria-label="'.$e($labels['centre']).'">'.$nav.'</nav><main>'.$content.$actions.'<p class="legal-feedback" role="status"></p></main></div><footer><a href="/legal?lang='.$locale.'">'.$e($labels['centre']).'</a><span>PTYS Technologies L.L.C.</span><a href="mailto:info@ptys.com.tr">info@ptys.com.tr</a></footer></body></html>';
}
function nodenoLegalHandle(string $path,string $method,string $private):void {
 if(!in_array($method,['GET','HEAD'],true)){nodenoError(405,'method_not_allowed');return;}
 if(!preg_match('~^/legal(?:/([a-z-]{1,40}))?/?$~D',$path,$match)){nodenoError(404,'not_found');return;}
 require_once $private.'/visitor-market.php';$visitor=nodenoVisitorMarket($_SERVER,$private);$locale=nodenoInitialLocale($_GET['lang']??null,$_COOKIE['nodeno_language']??null,$visitor['country']);
 $runtime=nodenoRuntimeConfiguration();require_once $private.'/payment-admin.php';$root=nodenoAccountStorage($runtime['storageRoot']??dirname($private).'/nodeno-data');$cfg=nodenoPaymentConfiguration(nodenoControlDatabase($root),$root);
 try{$html=nodenoLegalPage(nodenoLegalCorpus($private,$locale),$match[1]??'',$cfg['seller']??[]);}catch(InvalidArgumentException $e){nodenoError(404,'not_found');return;}
 $headers=['Cache-Control'=>'no-store'];if(($_GET['download']??null)==='1'){$headers['Content-Disposition']='attachment; filename="NODENO-'.($match[1]??'legal').'-'.$locale.'.html"';$css=rtrim($_SERVER['DOCUMENT_ROOT']??dirname(__DIR__).'/web','/\\').'/legal.css';$html=str_replace('<link rel="stylesheet" href="/legal.css?v=storefront-recovery-20261112-r1">','<style>'.file_get_contents($css).'</style>',$html);$html=preg_replace('~<script\b[^>]*>.*?</script>~s','',$html);}
 nodenoRespond($html,200,'text/html; charset=utf-8',$headers);
}
